"use client";

import dynamic from "next/dynamic";
import { useRef, useEffect, useState } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Zap, Rocket, ArrowRight } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { cn } from "@/lib/utils";

const HeroCube = dynamic(
  () => import("@/components/HeroCube").then((m) => ({ default: m.HeroCube })),
  {
    ssr: false,
    loading: () => (
      <div
        className="flex h-full w-full items-center justify-center border-none bg-transparent"
        aria-hidden
      >
        <div className="h-24 w-24 animate-pulse rounded-xl border border-emerald-500/20 bg-zinc-900/40" />
      </div>
    ),
  }
);

const sectionVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { duration: 0.4, ease: "easeOut" as const },
  },
};

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.12,
      delayChildren: 0.08,
    },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 14 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] as [number, number, number, number] },
  },
};

/** Lightweight 3D floating card – CSS 3D + optional mouse parallax. No heavy libs for PageSpeed. */
function Hero3DVisual() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const [mounted, setMounted] = useState(false);
  const mouseRef = useRef({ x: 0, y: 0 });
  const rafRef = useRef<number>(0);
  const transformRef = useRef({ rotateX: 0, rotateY: 0 });

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted || typeof window === "undefined") return;
    const wrap = wrapRef.current;
    if (!wrap) return;

    const throttleMs = 50;
    let last = 0;

    const onMove = (e: MouseEvent) => {
      const now = Date.now();
      if (now - last < throttleMs) return;
      last = now;
      mouseRef.current = { x: e.clientX, y: e.clientY };
    };

    const update = () => {
      rafRef.current = requestAnimationFrame(update);
      const { x, y } = mouseRef.current;
      const rect = wrap.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = (x - cx) / rect.width;
      const dy = (y - cy) / rect.height;
      const maxTilt = 12;
      const targetX = dy * maxTilt;
      const targetY = -dx * maxTilt;
      const t = 0.08;
      transformRef.current.rotateX += (targetX - transformRef.current.rotateX) * t;
      transformRef.current.rotateY += (targetY - transformRef.current.rotateY) * t;
      const { rotateX, rotateY } = transformRef.current;
      wrap.style.setProperty("--hero-3d-x", `${rotateX}deg`);
      wrap.style.setProperty("--hero-3d-y", `${rotateY}deg`);
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    rafRef.current = requestAnimationFrame(update);
    return () => {
      window.removeEventListener("mousemove", onMove);
      cancelAnimationFrame(rafRef.current);
    };
  }, [mounted]);

  return (
    <div
      ref={wrapRef}
      className="relative flex min-h-[200px] w-full items-center justify-center md:min-h-[320px]"
      style={{
        transform: "perspective(800px)",
        // CSS vars set by JS for parallax
        ["--hero-3d-x" as string]: "0deg",
        ["--hero-3d-y" as string]: "0deg",
      }}
    >
      {/* Outer glow */}
      <div
        aria-hidden
        className="absolute inset-0 flex items-center justify-center"
        style={{
          background: "radial-gradient(circle, rgba(16,185,129,0.15) 0%, transparent 60%)",
          transform: "scale(1.2)",
        }}
      />
      {/* 3D card – pure CSS transform; wrapper has float animation in globals */}
      <div className="hero-3d-float-wrapper">
        <div
          className="hero-3d-card relative h-[180px] w-[280px] rounded-2xl border border-zinc-700/80 bg-zinc-900/60 shadow-2xl backdrop-blur-md md:h-[220px] md:w-[320px]"
          style={{
          transformStyle: "preserve-3d",
          transform:
            "rotateX(var(--hero-3d-x, 0deg)) rotateY(var(--hero-3d-y, 0deg)) translateZ(0)",
          boxShadow:
            "0 25px 50px -12px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.05), 0 0 40px -10px rgba(16,185,129,0.2)",
        }}
      >
        {/* Inner gradient overlay */}
        <div
          className="absolute inset-0 rounded-2xl opacity-60"
          style={{
            background:
              "linear-gradient(135deg, rgba(16,185,129,0.12) 0%, transparent 50%, rgba(16,185,129,0.06) 100%)",
          }}
        />
        {/* Fake UI lines – decorative only */}
        <div className="absolute left-5 top-5 right-5 flex gap-2">
          <span className="h-2 w-12 rounded-full bg-zinc-600/80" />
          <span className="h-2 w-8 rounded-full bg-zinc-600/60" />
          <span className="h-2 w-6 rounded-full bg-zinc-600/40" />
        </div>
        <div className="absolute bottom-5 left-5 right-5 space-y-2">
          <div className="h-2 w-full rounded-full bg-zinc-700/50" />
          <div className="h-2 w-3/4 rounded-full bg-zinc-700/30" />
        </div>
        </div>
      </div>
    </div>
  );
}

export function HeroSection() {
  const { dict, localeSegment } = useLanguage();
  const h = dict.hero;

  return (
    <motion.section
      id="hero"
      className="relative z-0 flex min-h-[70vh] w-full flex-col overflow-hidden bg-zinc-950 px-5 pt-24 pb-12 sm:min-h-[75vh] sm:px-6 sm:pt-24 sm:pb-16 md:min-h-[80vh] md:pt-28 md:pb-20"
      aria-labelledby="hero-heading"
      variants={sectionVariants}
      initial="hidden"
      animate="visible"
    >
      {/* Tło: siatka + gradient */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 z-0"
        style={{
          backgroundImage: `
            linear-gradient(to right, rgba(255,255,255,0.03) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(255,255,255,0.03) 1px, transparent 1px)
          `,
          backgroundSize: "32px 32px",
        }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 z-0"
        style={{
          background: `
            radial-gradient(ellipse 100% 80% at 50% -20%, rgba(16,185,129,0.18) 0%, transparent 55%),
            radial-gradient(ellipse 80% 50% at 50% 60%, rgba(16,185,129,0.06) 0%, transparent 50%)
          `,
        }}
      />

      {/* Grid: desktop = 2 kolumny (kostka lewo, tekst prawo); mobile = tekst góra (order-1), kostka poniżej (order-2) z ograniczoną wysokością */}
      <div className="relative z-10 mx-auto grid w-full max-w-6xl flex-1 grid-cols-1 items-center gap-8 lg:grid-cols-2 lg:gap-12">
        {/* Lewa kolumna (desktop): Kostka 3D. Na mobile pod tekstem, max 40vh żeby nie rozpychała. */}
        <motion.div
          layout
          className="relative order-2 flex h-[40vh] min-h-[240px] w-full max-h-[380px] items-center justify-center bg-transparent md:max-h-none lg:order-1 lg:h-[600px]"
          style={{ background: "transparent" }}
          variants={containerVariants}
          initial="hidden"
          animate="visible"
        >
          {/* Premium Glow – promieniowa poświata pod kostką */}
          <div
            aria-hidden
            className="absolute inset-0 -z-10 blur-2xl pointer-events-none"
            style={{
              background: "radial-gradient(circle at center, rgba(16,185,129,0.15) 0%, transparent 50%, transparent 100%)",
            }}
          />
          <motion.div
            variants={itemVariants}
            className="relative z-0 h-full w-full cursor-grab border-none bg-transparent active:cursor-grabbing"
            style={{ background: "transparent" }}
          >
            <HeroCube />
          </motion.div>
        </motion.div>

        {/* Prawa kolumna (desktop): Tekst i CTA – na mobile na górze (order-1) */}
        <motion.div
          layout
          className="order-1 flex flex-col items-center text-center lg:order-2 lg:items-start lg:text-left"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
        >
          <motion.p
            layout
            variants={itemVariants}
            className="mb-5 flex w-fit items-center gap-2 rounded-full border border-emerald-500/40 bg-emerald-950/50 px-4 py-1.5 text-xs font-medium uppercase tracking-[0.18em] text-emerald-300/90 backdrop-blur-sm sm:text-sm"
          >
            <Zap className="size-3.5 text-emerald-400" aria-hidden />
            {h.badge}
          </motion.p>

          <motion.h1
            id="hero-heading"
            layout
            variants={itemVariants}
            className={cn(
              "mb-5 text-2xl font-bold leading-tight tracking-tight text-zinc-100 text-balance",
              "sm:text-3xl md:text-4xl lg:text-5xl"
            )}
          >
            {h.headline}
            {h.headlineAccent ? (
              <>
                {" "}
                <span className="text-emerald-500">{h.headlineAccent}</span>
                {h.headlineEnd}
              </>
            ) : null}
          </motion.h1>

          <motion.p
            layout
            variants={itemVariants}
            className="mb-6 max-w-lg text-sm leading-relaxed text-zinc-400 text-balance sm:mb-8 sm:text-base"
          >
            {h.subtext}
          </motion.p>

          <motion.div
            variants={itemVariants}
            className="flex w-full flex-col gap-3 sm:w-auto sm:flex-row sm:gap-4"
          >
            <Button
              asChild
              className="w-full rounded-lg border-none bg-gradient-to-r from-emerald-600 to-emerald-400 px-8 py-6 font-semibold text-white shadow-[0_0_20px_rgba(16,185,129,0.4)] transition-all duration-300 hover:scale-105 hover:shadow-[0_0_30px_rgba(16,185,129,0.6)] sm:w-auto"
            >
              <Link href={`/${localeSegment}/kreator`}>
                <Rocket className="mr-2 size-5 shrink-0" aria-hidden />
                {h.ctaPrimary}
              </Link>
            </Button>
            <Button
              asChild
              className="w-full rounded-lg border border-white/10 bg-white/5 px-8 py-6 text-white backdrop-blur-md transition-all duration-300 hover:scale-105 hover:border-white/20 hover:bg-white/10 sm:w-auto"
            >
              <Link href={`/${localeSegment}#projekty`}>
                {h.ctaSecondary}
                <ArrowRight className="ml-2 size-5 shrink-0" aria-hidden />
              </Link>
            </Button>
          </motion.div>
        </motion.div>
      </div>
    </motion.section>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { ArrowRight, Sparkles, Send, Zap, Rocket, Code, LayoutTemplate, X, Loader2 } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";

export function KreatorCTA() {
  const { dict, localeSegment } = useLanguage();
  const k = dict.kreator as {
    ctaHeadlineStart?: string;
    ctaHeadlineHighlight?: string;
    ctaSubtext?: string;
    ctaTopic1Title?: string;
    ctaTopic1Desc?: string;
    ctaTopic2Title?: string;
    ctaTopic2Desc?: string;
    ctaTopic3Title?: string;
    ctaTopic3Desc?: string;
    ctaTopic4Title?: string;
    ctaTopic4Desc?: string;
    ctaInputPlaceholder?: string;
    ctaFreeQuote?: string;
    ctaModalTitle?: string;
    ctaModalSubtext?: string;
    ctaModalEmailPlaceholder?: string;
    ctaModalSubmit?: string;
  };

  const [briefModalOpen, setBriefModalOpen] = useState(false);
  const [briefEmail, setBriefEmail] = useState("");
  const [briefSending, setBriefSending] = useState(false);
  const [message, setMessage] = useState("");

  const handleSendBrief = async () => {
    setBriefSending(true);
    // TODO: podepnij API np. fetch('/api/send-workshop-brief', { method: 'POST', body: JSON.stringify({ email: briefEmail, message }) })
    await new Promise((r) => setTimeout(r, 2000));
    setBriefSending(false);
    setBriefModalOpen(false);
    setBriefEmail("");
  };

  const topics = [
    { id: 1, icon: LayoutTemplate, title: k.ctaTopic1Title ?? "Strona Wizytówka", desc: k.ctaTopic1Desc ?? "Nowoczesna, ultraszybka strona" },
    { id: 2, icon: Code, title: k.ctaTopic2Title ?? "Aplikacja Webowa", desc: k.ctaTopic2Desc ?? "Zaawansowany system lub portal" },
    { id: 3, icon: Rocket, title: k.ctaTopic3Title ?? "MVP od zera", desc: k.ctaTopic3Desc ?? "Szybki start dla Twojego startupu" },
    { id: 4, icon: Zap, title: k.ctaTopic4Title ?? "Migracja na Next.js", desc: k.ctaTopic4Desc ?? "Większa wydajność i lepsze SEO" },
  ];

  return (
    <section
      id="kreator"
      className="relative scroll-mt-20 border-t border-zinc-800/80 w-full font-sans my-24 px-4 sm:px-6"
      aria-labelledby="kreator-cta-heading"
    >
      <div className="relative w-full max-w-4xl mx-auto">
        {/* Tło - Mistyczny Orb */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/20 rounded-full blur-[120px] pointer-events-none" aria-hidden />

        <div className="relative rounded-[2rem] bg-zinc-950/40 shadow-[inset_0_1px_0_0_rgba(255,255,255,0.08)] ring-1 ring-white/[0.08] backdrop-blur-2xl p-6 sm:p-10 overflow-hidden">
          <div className="text-center mb-10">
            <h2 id="kreator-cta-heading" className="text-3xl font-light tracking-tight text-white mb-3">
              {k.ctaHeadlineStart ?? "Rozpocznijmy "}
              <span className="font-semibold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-indigo-400 bg-[length:200%_auto] animate-pulse">
                {k.ctaHeadlineHighlight ?? "nowy projekt."}
              </span>
            </h2>
            <p className="text-zinc-400 text-sm sm:text-base">
              {k.ctaSubtext ?? "Wybierz temat i opisz krótko swój pomysł, a ja zajmę się resztą."}
            </p>
          </div>

          {/* Pływające kafelki z opcjami */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-10">
            {topics.map((t) => {
              const Icon = t.icon;
              return (
                <button
                  key={t.id}
                  type="button"
                  className="group relative overflow-hidden rounded-2xl bg-white/[0.02] p-5 text-left shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05)] ring-1 ring-white/[0.05] backdrop-blur-md transition-all duration-300 ease-out hover:bg-white/[0.06] hover:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.1),0_8px_20px_rgba(0,0,0,0.4)] hover:-translate-y-0.5 flex items-start gap-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/20 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950"
                >
                  <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/0 via-transparent to-purple-500/0 group-hover:from-indigo-500/10 group-hover:to-purple-500/10 transition-all duration-500 pointer-events-none" aria-hidden />
                  <div className="relative mt-0.5 text-zinc-500 group-hover:text-indigo-400 transition-colors duration-300">
                    <Icon className="w-5 h-5" aria-hidden />
                  </div>
                  <div className="relative">
                    <h3 className="text-zinc-200 font-medium mb-1 group-hover:text-white transition-colors">{t.title}</h3>
                    <p className="text-xs text-zinc-500 group-hover:text-zinc-400 transition-colors">{t.desc}</p>
                  </div>
                </button>
              );
            })}
          </div>

          {/* Input & Główny Przycisk CTA */}
          <div className="flex flex-col sm:flex-row gap-4 items-center relative z-10">
            <div className="relative flex-1 w-full">
              <input
                type="text"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder={k.ctaInputPlaceholder ?? "Napisz mi krótko o swoim pomyśle..."}
                className="w-full h-14 pl-6 pr-14 rounded-full bg-zinc-900/50 text-zinc-100 placeholder:text-zinc-500 outline-none ring-1 ring-white/[0.05] focus:ring-white/[0.2] focus:bg-zinc-900/80 transition-all duration-300 shadow-[inset_0_1px_0_0_rgba(255,255,255,0.03)]"
                aria-label={k.ctaInputPlaceholder ?? "Opisz swój pomysł"}
              />
              <Link
                href="#contact"
                className="absolute right-2 top-2 bottom-2 w-10 bg-white/[0.05] hover:bg-white/[0.1] rounded-full flex items-center justify-center text-zinc-500 hover:text-white transition-colors duration-300"
                aria-label="Wyślij"
              >
                <Send className="w-4 h-4" />
              </Link>
            </div>

            <button
              type="button"
              onClick={() => setBriefModalOpen(true)}
              className="group relative h-14 px-8 rounded-full bg-zinc-950 text-white font-medium transition-all duration-300 shadow-[0_0_0_1px_rgba(255,255,255,0.1)] hover:shadow-[0_0_30px_-5px_rgba(139,92,246,0.6),0_0_0_1px_rgba(139,92,246,0.6)] flex items-center gap-2 overflow-hidden w-full sm:w-auto justify-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/30 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/20 to-purple-500/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" aria-hidden />
              <Sparkles className="w-4 h-4 text-indigo-400 group-hover:text-white transition-colors shrink-0" aria-hidden />
              <span className="relative z-10">{k.ctaFreeQuote ?? "Darmowa wycena"}</span>
            </button>
          </div>
        </div>
      </div>

      {/* Modal Wyceny (Glassmorphism) */}
      {briefModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true" aria-labelledby="brief-modal-title">
          <div className="absolute inset-0 bg-black/70 backdrop-blur-md" onClick={() => setBriefModalOpen(false)} aria-hidden />
          <div className="relative w-full max-w-md bg-zinc-900/90 rounded-3xl p-8 shadow-[0_20px_40px_rgba(0,0,0,0.5),inset_0_1px_0_0_rgba(255,255,255,0.1)] ring-1 ring-white/[0.08] backdrop-blur-xl animate-in fade-in zoom-in-95 duration-200">
            <button
              type="button"
              onClick={() => setBriefModalOpen(false)}
              className="absolute top-5 right-5 text-zinc-500 hover:text-white transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/20 rounded-lg"
              aria-label="Zamknij"
            >
              <X className="w-5 h-5" />
            </button>
            <h3 id="brief-modal-title" className="text-xl font-medium text-white mb-2">
              {k.ctaModalTitle ?? "Gdzie wysłać wycenę?"}
            </h3>
            <p className="text-sm text-zinc-400 mb-8">
              {k.ctaModalSubtext ?? "Podaj swój adres email, na który wyślę bezpłatną estymację oraz dalsze kroki."}
            </p>

            <div className="space-y-4">
              <input
                type="email"
                value={briefEmail}
                onChange={(e) => setBriefEmail(e.target.value)}
                placeholder={k.ctaModalEmailPlaceholder ?? "twoj@email.com"}
                className="w-full h-12 px-4 rounded-xl bg-zinc-950/50 text-zinc-100 placeholder:text-zinc-500 outline-none ring-1 ring-white/[0.1] focus:ring-indigo-500/50 transition-all shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05)]"
                autoFocus
                disabled={briefSending}
                aria-label="Email"
              />
              <button
                type="button"
                onClick={handleSendBrief}
                disabled={!briefEmail.trim() || briefSending}
                className="w-full h-12 rounded-xl bg-white text-black font-medium flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-zinc-200 transition-colors shadow-[0_0_20px_rgba(255,255,255,0.1)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/30"
              >
                {briefSending ? (
                  <Loader2 className="w-5 h-5 animate-spin text-zinc-500" aria-hidden />
                ) : (
                  <>
                    {k.ctaModalSubmit ?? "Wyślij zapytanie"}
                    <ArrowRight className="w-4 h-4" aria-hidden />
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

"use client";

import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { Layers, Brain, Wallet, Cloud } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { cn } from "@/lib/utils";

const BLOCK_ICONS = [Layers, Brain, Wallet, Cloud] as const;

const containerVariants = {
  hidden: {},
  visible: {
    transition: { staggerChildren: 0.1, delayChildren: 0.1 },
  },
};

const blockVariants = {
  hidden: { opacity: 0, scale: 0.92, y: 20 },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: { type: "spring" as const, stiffness: 400, damping: 28 },
  },
};

export function ModularStack() {
  const sectionRef = useRef<HTMLElement>(null);
  const isInView = useInView(sectionRef, { once: true, amount: 0.15 });
  const { dict, lang } = useLanguage();
  const blocks = dict.modularStack.blocks;

  return (
    <section
      ref={sectionRef}
      id="modular-stack"
      className="relative my-24 border-t border-zinc-800 bg-black/20 px-5 py-16 pb-[max(2rem,env(safe-area-inset-bottom))] backdrop-blur-sm sm:px-6 md:py-24 md:pb-24"
      aria-labelledby="modular-stack-heading"
    >
      <div className="mx-auto max-w-5xl">
        <motion.header
          layout
          initial={{ opacity: 0, y: 12 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.4 }}
          className="mb-12 text-center"
        >
          <h2
            id="modular-stack-heading"
            className="mb-3 text-2xl font-bold tracking-tight text-zinc-100 md:text-3xl"
          >
            {dict.modularStack.heading}
          </h2>
          <p className="mx-auto max-w-2xl text-sm leading-relaxed text-zinc-400 md:text-base">
            {dict.modularStack.subtext}
          </p>
        </motion.header>

        <motion.div
          className="relative grid grid-cols-2 gap-4 md:grid-cols-4 md:gap-6"
          variants={containerVariants}
          initial="hidden"
          animate={isInView ? "visible" : "hidden"}
