} from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { cn } from "@/lib/utils";
import { SpotlightCard } from "@/components/SpotlightCard";

const otherProjectsMeta: Array<{
  titleKey: "saasStarter" | "aiAutomations";
  title: string;
  href: string;
  span: string;
